        Objects.requireNonNull(expiresAt, "expiresAt must not be null");
    }

    public OperatorSessionPayload withViewAsOverlay(String targetRoleCode) {
        boolean active = targetRoleCode != null && !targetRoleCode.isBlank();
        String normalizedRole = active ? targetRoleCode.trim() : null;
        return new OperatorSessionPayload(
                sessionId,
                userId,
                workspaceEmail,
                displayName,
                roles,
                permissions,
                normalizedRole,
                active,
                issuedAt,
                expiresAt);
